window.AUTH=window.AUTH||{};window.AUTH["17-1094"]={"d":"17-1094","id":"2018/17-1094","n":"Nutraceutical Corp. v. Lambert","briefs":[{"k":"petitioner","label":"Brief of petitioner Nutraceutical Corporation","date":"2018-08-20","url":"https://www.supremecourt.gov/DocketPDF/17/17-1094/60055/20180820144206693_17-1094%20Petitioner%20Brief.pdf","side":"pet","n":61},{"k":"respondent","label":"Brief of respondent Troy Lambert","date":"2018-10-01","url":"https://www.supremecourt.gov/DocketPDF/17/17-1094/65274/20181001113252799_17-1094%20Brief%20for%20Respondent--PDFA.pdf","side":"res","n":115},{"k":"reply","label":"Reply of petitioner Nutraceutical Corporation","date":"2018-10-31","url":"https://www.supremecourt.gov/DocketPDF/17/17-1094/68579/20181031131648808_17-1094%20Reply%20Brief.pdf","side":"pet","n":75}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1094_bq7d.pdf","tr":true,"items":[{"t":"case","label":"Bank of Nova Scotia v. United States","cite":"487 U.S. 250","y":1988,"id":"1987/87-578","sc":1,"op":1,"sum":"The District Court dismissed an indictment against petitioners and others on the basis of prosecutorial misconduct and irregularities in the grand jury proceedings, finding that dismissal was proper due to violations of Federal Rule of Criminal Procedure 6 and under the \"totality of the circumstances,\" including \"numerous\" violations of Rules 6(d) and (e); violations of 18 U. S. C. §§ 6002 and 6003 and of the Fifth …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 20","2":"13"}},{"t":"case","label":"Beck v. Boeing Co.","cite":"320 F.3d 1021","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/320/1021/","by":{"0":"22"}},{"t":"case","label":"Blair v. Equifax Check Servs.","cite":"181 F.3d 832","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/181/832/","sum":"Noting that the lack of an automatic stay provision demonstrates that “Rule 23(f) is drafted to avoid delay”.","sumSrc":"brief:0","by":{"0":"32, 44","2":"6, 7, 9"}},{"t":"case","label":"Bowles v. Russel","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"ar":2,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"passim","1":"28, 29, 30","2":"23"}},{"t":"case","label":"Budinich v. Becton Dickinson & Co.","cite":"486 U.S. 196","y":1988,"id":"1987/87-283","sc":1,"op":1,"sum":"In petitioner's employment compensation action, which respondent removed from a Colorado state court to the Federal District Court on the basis of diversity of citizenship, judgment was entered on the jury's verdict for petitioner in an amount considerably less than he had sought. Petitioner timely filed new-trial motions and a motion for attorney's fees under Colorado law. On May 14, 1984, the court denied the new …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Cal. Pub. Employees’ Ret. Sys. v. ANZ Sec., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Carlisle v. United States","cite":"517 U.S. 416","y":1996,"id":"1995/94-9247","sc":1,"op":4,"ar":11,"sum":"The Court held that the District Court had no authority to grant the petitioner's motion for judgment of acquittal filed one day outside the Rule 29(c) time limit.","sumSrc":"Oyez","by":{"0":"passim","1":"30, 44, 45, 46","2":"passim"}},{"t":"case","label":"Carpenter v. Boeing Co.","cite":"456 F.3d 1183","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/456/1183/","by":{"0":"34, 44","2":"7, 10"}},{"t":"case","label":"Chamberlan v. Ford Motor Co.","cite":"402 F.3d 952","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/402/952/","by":{"0":"29, 31"}},{"t":"case","label":"Delta Airlines v. Butler","cite":"383 F.3d 1143","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/1143/","sum":"Rejecting Rule 23(f) petition filed late as a result of attorney error, holding “[t]he Federal Rules of Appellate Procedure specifically foreclose appellate courts from granting an extension of time to file a petition for permission to appeal”.","sumSrc":"brief:0","by":{"0":"10, 21, 22, 25","2":"17"}},{"t":"case","label":"Eastman v. First Data Corp.","cite":"736 F.3d 675","y":2013,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/736/675/","sum":"Rejecting Rule 23(f) petition that was filed late as a result of counsel’s mistake because Appellate Rule 26(b)(1) “clearly states that this Court cannot extend the time for filing a petition for permission to appeal”.","sumSrc":"brief:0","by":{"0":"24, 43","2":"17"}},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"op":1,"ar":2,"sum":"The Court held that Federal Rule of Criminal Procedure 33, which creates a seven-day limit for filing a motion for a new trial that is not based on newly discovered evidence, was not a jurisdictional rule but rather a claim-processing one.","sumSrc":"Oyez","by":{"0":"passim","1":"32, 33, 40","2":"13, 14"}},{"t":"case","label":"Flanagan v. United States","cite":"465 U.S. 259","y":1984,"id":"1983/82-374","sc":1,"sum":"The disqualification order was not immediately appealable under § 1291, and hence the Court of Appeals had no jurisdiction to review the order prior to entry of final judgment in the case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Fleischman v. Albany Med. Ctr.","cite":"639 F.3d 28","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/639/28/","op":1,"sum":"Recognizing “Rule 23(f)’s aim of providing an opportunity for interlocutory appeal, but confining that opportunity within narrow limits, so as to avoid disruption and delay to the proceedings below”.","sumSrc":"brief:0","by":{"0":"10, 25, 29, 30, 44","2":"7, 8, 11, 17, 20"}},{"t":"case","label":"Gary v. Sheahan","cite":"188 F.3d 891","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/188/891/","op":1,"by":{"0":"11, 29, 30, 44","2":"7, 11, 20"}},{"t":"case","label":"Griggs v. Provident Consumer Discount Co.","cite":"459 U.S. 56","y":1982,"id":"1982/82-5082","sc":1,"sum":"The Court of Appeals' analysis of Rule 4(a)(4) is contrary to the language and purposes of the 1979 amendments to the Rules of Appellate Procedure. Prior to 1979, if a notice of appeal was fied pending disposition of a motion to vacate, alter, or amend the judgment it was generally held that the district court retained jurisdiction to decide the motion and the notice of appeal was adequate for purposes of beginning …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Gutierrez v. Johnson & Johnson","cite":"523 F.3d 187","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/523/187/","op":1,"sum":"Holding that where a district court “made no affirmative statements about the effect of the extension of time on Petitioners’ ability to appeal [under Rule 23(f)],” the “unique circumstances doctrine provides no relief”.","sumSrc":"brief:2","by":{"0":"passim","2":"passim"}},{"t":"case","label":"Hallstrom v. Tillamook Cty.","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 3619","2":"12"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Serv. of Chi.","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"op":2,"ar":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"0":"14, 15, 17, 19","1":"29, 40","2":"14"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"14, 15","1":"40","2":"14, 18"}},{"t":"case","label":"Hewitt v. Helms","cite":"459 U.S. 460","y":1983,"id":"1982/81-638","sc":1,"sum":"Following a riot in the Pennsylvania State Prison where he was an inmate, respondent was removed from his cell and the general prison population and confined to administrative segregation within the prison pending an investigation into his role in the riot. The next day respondent received notice of a misconduct charge against him. Five days after his transfer to administrative segregation a Hearing Committee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"0":"35, 38, 41","1":"passim","2":"22, 7"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"ar":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"35, 43","1":"21, 48"}},{"t":"case","label":"Jenkins v. BellSouth Corp.","cite":"491 F.3d 1288","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/491/1288/","by":{"0":"30, 36","2":"8, 10, 20"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"op":4,"ar":4,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"0":"passim","1":"18, 32, 44","2":"passim"}},{"t":"case","label":"Lambert v. Nutraceutical Corp.","cite":"870 F.3d 1170","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/870/1170/","op":2,"sum":"Finding equitable exceptions could apply if, for example, “a litigant took some other action similar to filing a motion for reconsideration within the fourteen-day deadline”.","sumSrc":"brief:2","by":{"0":"passim","1":"11, 13, 58","2":"passim"}},{"t":"case","label":"Lawrence v. Florida","cite":"549 U.S. 327","y":2007,"id":"2006/05-8820","sc":1,"sum":"The Court ruled 5-4 that the time a habeas petition is pending before the Supreme Court counts toward the one-year statute of limitations in the Antiterrorism and Effective Death Penalty Act. Section 2244(d)(2) of the Act stops the clock on the time limit while the prisoner appeals in state courts, but the Court ruled that appeals to the Supreme Court are not part of the process referred to in the Act.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Lienhart v. Dryvit Sys. Inc.","cite":"255 F.3d 138","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/255/138/","sum":"Explaining that Appellate Rule 5 was amended to apply to Rule 23(f) petitions.","sumSrc":"brief:0","by":{"0":"22"}},{"t":"case","label":"Main Drug, Inc. v. Aetna U.S. Healthcare, Inc.","cite":"475 F.3d 1228","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/475/1228/","sum":"Holding that Appellate Rule 2 and 26(b) “explicitly forbid us from suspending, even for good cause, the time requirements” for filing a petition for permission to appeal.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Manrique v. United States","cite":"137 S. Ct. 1266","y":2017,"id":"2016/15-7250","sc":1,"op":3,"sum":"The Court held that appellate courts do not have jurisdiction over an appeal of a restitution award when the judgment that awarded restitution was entered after the notice of appeal was filed.","sumSrc":"Oyez","by":{"0":"8, 14, 15, 16","1":"32, 33","2":"14, 18"}},{"t":"case","label":"McNamara v. Felderhof","cite":"410 F.3d 277","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/410/277/","op":1,"sum":"Recognizing that a motion for reconsideration of 2 Before December 1, 2009, Rules 59(e) and 23(f) were both subject to a 10-day deadline. an order denying class certification is a Rule 59 motion.","sumSrc":"brief:1","by":{"0":"13, 44","1":"10","2":"6, 7"}},{"t":"case","label":"Menominee Indian Tribe of Wis. v. United States","cite":"136 S. Ct. 750","y":2016,"id":"2015/14-510","sc":1,"sum":"The Court determined that there were no extraordinary circumstances out of the Menominee Indian Tribe’s control to toll the statute of limitations from running.","sumSrc":"Oyez","by":{"0":"passim","1":"56","2":"2, 22"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"137 S. Ct. 1702","y":2017,"id":"2016/15-457","sc":1,"op":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"0":"29","1":"31, 35, 51, 52"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"op":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Nucor Corp. v. Brown","cite":"760 F.3d 341","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/760/341/","op":1,"by":{"0":"30, 44","2":"7, 10"}},{"t":"case","label":"Osterneck v. Ernst & Whinney","cite":"489 U.S. 169","y":1989,"id":"1988/87-1201","sc":1,"sum":"Petitioners' motion for prejudgment interest constituted a Rule 59(e) motion and rendered ineffective under Rule 4(a)(4) their notice of appeal filed before a ruling on that motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"10, 28, 57, 58","2":"22, 23"}},{"t":"case","label":"Pace v. DiGuglielmo","cite":"544 U.S. 408","y":2005,"id":"2004/03-9627","sc":1,"sum":"The Court held that the federal statute of limitations barred Pace's petition, as it was filed beyond the deadline. Pace was not entitled to statutory tolling because a petition filed after a time limit, which does meet any exceptions to that limit, was no more \"properly filed\" than a petition filed after a time limit permitting no exception.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entm’t Grp.","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"sum":"When read in the context of all of Rule ll's signature provisions, the phrase \"person who signed\" connotes the individual signer mentioned at the outset of the Rule and authorizes a court to impose a sanction only against that individual. That is so even when the individual explicitly signs on behalfof the firm, since it is only the signature \"in the attorney's individual name\" which complies with the Rule's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Rudin v. Myles","cite":"781 F.3d 1043","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/781/1043/","by":{"0":"35"}},{"t":"case","label":"Sandin v. Conner","cite":"515 U.S. 472","y":1995,"id":"1994/93-1911","sc":1,"sum":"Neither the Hawaii prison regulation nor the Due Process Clause itself affords Conner a protected liberty interest that would entitle him to the procedural protections set forth in Wolff.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Shin v. Cobb Cty. Bd. of Educ.","cite":"248 F.3d 1061","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/248/1061/","by":{"0":"44","2":"6, 7"}},{"t":"case","label":"Thompson v. Immigration & Naturalization Service","cite":"375 U.S. 384","y":1964,"id":"1963/496","sc":1,"op":1,"sum":"In view of petitioner's reliance on the District Court's statement that his motions were timely filed, thus postponing the time to file an appeal, he should have a hearing on the merits. Harris Truck Lines, Inc., v. Cherry Meat Packers, Inc., 371 U. S. 215, followed. Certiorari granted; 318 F. 2d 681, judgment vacated and case remanded. Hal Witt for petitioner. Solicitor General Cox, Assistant Attorney General …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 41","1":"passim","2":"23"}},{"t":"case","label":"Torres v. Oakland Scavenger Co.","cite":"487 U.S. 312","y":1988,"id":"1987/86-1845","sc":1,"op":1,"sum":"Failure to file a notice of appeal in accordance with Federal Rule of Appellate Procedure 3(c)'s requirement that the notice \"specify the party or parties taking the appeal\" presents a jurisdictional bar to the appeal. The Rule's caveat that an appeal \"shall not be dismissed for [the notice's] informality of form or title\" does not aid petitioner, since his exclusion from the notice constitutes a failure to appeal …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","2":"15, 16, 17"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"20","2":"2, 12"}},{"t":"case","label":"United States v. Dieter","cite":"429 U.S. 6","y":1976,"id":"1976/75-1547","sc":1,"ar":4,"sum":"The 30-day limitation period prescribed by the Criminal Appeals Act and Fed. Rule App. Proc. 4 (b) for a Government appeal from an order dismissing an indictment ran from the date of the District Court's denial of the Government's motion to set aside the dismissal of the indictment against respondent, rather than from the date of the dismissal order, and hence the Government's appeal was timely where its notice of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43, 44","1":"14, 27","2":"7, 8"}},{"t":"case","label":"United States v. Healy","cite":"376 U.S. 75","y":1964,"id":"1963/64","sc":1,"ar":4,"sum":"The timely filing of a petition for a rehearing in a criminal case, no less than in a civil case, renders the judgment nonfinal for purposes of appeal until the court disposes of the petition, and in such an instance the 30-day period prescribed by Rule 11 (2) begins to run from the date of the denial of the petition for rehearing.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 43, 44","1":"14, 15, 27","2":"7, 8, 19"}},{"t":"case","label":"United States v. Ibarra","cite":"502 U.S. 1","y":1991,"id":"1991/90-1713","sc":1,"op":1,"ar":4,"sum":"The Government's appeal was timely. All motions for reconsideration are subsumed under one general rule-the rule laid down in Healy. If a merits inquiry were grafted onto the general rule, litigants would 1 UNITED STATES v. IBARRA","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"14, 27, 36","2":"7, 19"}},{"t":"case","label":"United States v. Lefler","cite":"880 F.2d 233","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/880/233/","sum":"Explaining that Dieter and Healy require a motion for reconsideration to be filed before the time to appeal expires.","sumSrc":"brief:0","by":{"0":"44"}},{"t":"case","label":"United States v. Robinson","cite":"361 U.S. 220","y":1960,"id":"1959/16","sc":1,"op":4,"sum":"Under the Federal Rules of Criminal Procedure, the filing of a notice of appeal in a criminal case after expiration of the time prescribed in Rule 37 (a) (2) does not confer jurisdiction upon the Court of Appeals, even though the District Court, proceeding under Rule 45 (b), has found that the late filing of the notice of appeal was the result of \"excusable neglect.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"44, 45","2":"passim"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"0":"12, 28, 36"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(d)(2)"],"by":{"0":"4"}},{"t":"rule","label":"Fed. R. App. P. 2","url":"https://www.law.cornell.edu/rules/frap/rule_2","by":{"0":"10, 21, 25, 26, 27","1":"41, 42","2":"passim"}},{"t":"rule","label":"Fed. R. App. P. 5","url":"https://www.law.cornell.edu/rules/frap/rule_5","subs":["(a)","(a)(2)","(d)(2)"],"by":{"0":"2, 9, 10, 21, 22","1":"17, 38, 36, 17, 37","2":"9, 19, passim"}},{"t":"rule","label":"Fed. R. App. P. 26","url":"https://www.law.cornell.edu/rules/frap/rule_26","subs":["(b)","(b)(1)","(b)(2)"],"by":{"0":"passim","1":"passim, 39","2":"passim, 16"}},{"t":"rule","label":"Fed. R. Civ. P. 6","url":"https://www.law.cornell.edu/rules/frcp/rule_6","subs":["(b)","(b)(2)"],"by":{"0":"24","1":"33"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(b)(3)","(f)","(g)(1)","(c)(1)(C)","(c)(2)(B)","(c)(3)(B)"],"by":{"0":"4, passim, 36","1":"43, 4, 8, 19, 19, 19, passim, 35, 38, 46, 51","2":"11, passim"}},{"t":"rule","label":"Fed. R. Crim. P. 45","url":"https://www.law.cornell.edu/rules/frcrmp/rule_45","subs":["(b)"],"by":{"0":"passim","1":"45","2":"1, 12, 13, 14, 15"}},{"t":"case","label":"Am. Pipe & Constr. Co. v. Utah","cite":"414 U.S. 538","y":1974,"id":"1973/72-1195","sc":1,"sum":"The Court held that commencing a class action suspends all applicable statutes of limitations against members of that class who would have been parties had the suit been allowed to continue as a class action.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Aspen Mining & Smelting Co. v. Billings","cite":"150 U.S. 31","y":1893,"id":"scdb/1893-005","sc":1,"sum":"An'order allowing an appeal to this court is, so long as the appeal remains unperfected and the cause has not passed into the jurisdiction of the appellate tribunal, subject to the general power of a Circuit Court over its own judgments, decrees, and orders during the existence of the term at which they are made,","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Auto Servs. Co. v. KPMG, LLP","cite":"537 F.3d 853","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/537/853/","sum":"Noting that for purposes of Civil Rules 54(a) and 59(e) and Appellate Rule 4(a)(4)(A)(iv), a “‘judgment’ encompasses both a final judgment and an appealable interlocutory order”.","sumSrc":"brief:1","by":{"1":"11"}},{"t":"case","label":"Bankers Tr. Co. v. Mallis","cite":"435 U.S. 381","y":1978,"id":"1977/76-1359","sc":1,"sum":"In dismissing respondents' action against petitioner under § 10 (b) of the Securities Exchange Act of 1934, the District Court failed to set forth the judgment in a separate document as required by Fed. Rule Civ. Proc.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Becker v. Montgomery","cite":"532 U.S. 757","y":2001,"id":"2000/00-6374","sc":1,"sum":"The Court held that when a party files a timely notice of appeal in district court, the failure to sign the notice does not require the court of appeals to dismiss the appeal.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Bristol-Myers Squibb Co. v. Super. Ct. of Cal.","cite":"137 S. Ct. 1452","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/1452/","sc":1,"by":{"1":"41"}},{"t":"case","label":"Carter v. Hodge","cite":"726 F.3d 917","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/726/917/","by":{"1":"34"}},{"t":"case","label":"China Agritech, Inc. v. Resh","cite":"138 S. Ct. 1800","y":2018,"id":"2017/17-432","sc":1,"sum":"The Court decided that upon denial of class certification, a putative class member may not, in lieu of promptly joining an existing suit or promptly filing a individual action, commence a class action anew beyond the time allowed by the applicable statute of limitations.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Crown, Cork & Seal Co. v. Parker","cite":"462 U.S. 345","y":1983,"id":"1982/82-118","sc":1,"sum":"The filing of the class action tolled the statute of limitations for respondent and other members of the putative class. Since respondent did not receive his Notice of Right to Sue until after the class action was filed, he retained a full 90 days in which to bring suit after class certification was denied, and hence his suit was timely filed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Day v. McDonough","cite":"547 U.S. 198","y":2006,"id":"2005/04-1324","sc":1,"sum":"The Court affirmed the judgment of the Circuit Court and ruled that the District Court was within its discretion when it dismissed Day's petition.","sumSrc":"Oyez","by":{"1":"54"}},{"t":"case","label":"Foman v. Davis","cite":"371 U.S. 178","y":1962,"id":"1962/41","sc":1,"sum":"A Federal District Court dismissed petitioner's complaint in a civil action for failure to state a claim upon which relief might be granted. Petitioner promptly moved to vacate the judgment and amend the complaint so as to state an alternative theory for recovery. Before the Court ruled on those motions, petitioner filed notice of appeal from the judgment of dismissal. Subsequently, the District Court denied the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Fry v. Pliler","cite":"551 U.S. 112","y":2007,"id":"2006/06-5247","sc":1,"sum":"The Court held unanimously that a federal court \"must assess the prejudicial impact of constitutional error in a state-court criminal trial under the 'substantial and injurious effect' standard set forth in Brecht , [...] whether or not the state appellate court recognized the error and reviewed it for harmlessness under the 'harmless beyond a reasonable doubt' standard set forth in Chapman .\" The opinion by Justice Antonin Scalia ruled that neither the Court's previous precedents nor the Antiterrorism and Effective Death Penalty Act of 1996 required courts to use the more stringent Chapman standard in such cases.","sumSrc":"Oyez","by":{"1":"53, 54"}},{"t":"case","label":"Gelder v. Coxcom Inc.","cite":"696 F.3d 966","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/696/966/","sum":"Recognizing that the timely filing of a motion listed in Appellate Rule 4(a)(4)(A) postpones the time to petition for permission to appeal under Rule 23(f).","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"Glover v. Standard Fed. Bank","cite":"283 F.3d 953","y":2002,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/283/953/","by":{"1":"20","2":"10"}},{"t":"case","label":"Harris Truck Lines, Inc. v. Cherry Meat Packers, Inc.","cite":"371 U.S. 215","y":1962,"id":"1962/435","sc":1,"op":1,"ar":2,"sum":"Since petitioner had relied-on the District Court's ruling extending the time within which to appeal and petitioner would suffer a hardship if it were set aside, the Court of Appeals should have let it stand. Pp. 215-217. 303 F. 2d 609, judgment vacated and case remanded. Harlan L. Hackbert for petitioner. John J. Kelly, Jr. for respondent.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28, 30, 44, 45","2":"23"}},{"t":"case","label":"Henderson v. Shinseki","cite":"589 F.3d 1201","y":2009,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/589/1201/","by":{"1":"40, 41"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Holmberg v. Armbrecht","cite":"327 U.S. 392","y":1946,"id":"scdb/1945-049","sc":1,"sum":"1. Decision of a suit in a federal court to enforce a federally created equitable right is not controlled by the statute of limitations of the State of the forum. Guaranty Trust Co. v. York, 326 U. S. 99, distinguished. Accordingly, a class suit by creditors of a joint stock land bank to enforce the liability imposed upon shareholders of the bank by § 16 of the Federal Farm Loan Act is not barred by the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 26"}},{"t":"case","label":"Int’l Union of Operating Eng’rs, Local 18 v. NLRB","cite":"837 F.3d 593","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/837/593/","by":{"1":"33"}},{"t":"case","label":"Izumi Seimitsu Kogyo Kabushiki Kaisha v. U.S. Philips Corp.","cite":"510 U.S. 27","y":1993,"id":"1993/92-1123","sc":1,"sum":"Petitioner Izumi Seimitsu Kogyo Kabushiki Kaisha was a party at the first trial in an action brought against it and respondent Windmere Corporation by respondent U. S. Philips Corporation, but was not a party to the second trial, in which Windmere prevailed. While the judgments from the second trial were on appeal, respondents reached a settlement and filed a joint motion to vacate the District Court's judgments. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"53, 54"}},{"t":"case","label":"Jaquay v. Principi","cite":"304 F.3d 1276","y":2002,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/304/1276/","by":{"1":"41"}},{"t":"case","label":"Johnson v. City of Shelby","cite":"135 S. Ct. 346","y":2014,"id":"2014/13-1318","sc":1,"sum":"The Court held that federal pleading rules require only a “short plain statement of the claim showing that the pleader is entitled to relief,” not a complete statement of the legal theory supporting the claim.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Khan v. U.S. Dep’t of Justice","cite":"494 F.3d 255","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/494/255/","sum":"Concluding that Bowles did not alter the ability of a court to recognize equitable exceptions to nonjurisdictional deadlines for filing an appeal.","sumSrc":"brief:1","by":{"1":"29, 34"}},{"t":"case","label":"Klehr v. A.O. Smith Corp.","cite":"521 U.S. 179","y":1997,"id":"1996/96-663","sc":1,"sum":"No and No. Justice Stephen Breyer wrote the opinion for a unanimous Court. The \"last predicate rule...lengthens the limitations period dramatically\" and thereby contradicts Congress's intention of ensuring a time limit for civil RICO claims.","sumSrc":"Oyez","by":{"1":"53, 54"}},{"t":"case","label":"Legg v. Ulster Cty.","cite":"820 F.3d 67","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/820/67/","by":{"1":"34"}},{"t":"case","label":"Liberty Oil Co. v. Condon Nat’l Bank","cite":"260 U.S. 235","y":1922,"id":"scdb/1922-035","sc":1,"sum":"1. Where a defendant, suedat law in the District Court for money had and received, avers by answer and.cross-petition that it is a stakeholder of the money in question, offers to pay it into court,\" and prays that the other claimants be made parties, that the issue be litigated between them and the plaintiff, and that the defendant be dischárged' from liability, the proceeding becomes an equitable one, an …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Lichtenberg v. Besicorp Grp. Inc.","cite":"204 F.3d 397","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/204/397/","sum":"Recognizing that a “judgment” under the Civil Rules encompasses both a final judgment and an appealable interlocutory order.","sumSrc":"brief:1","by":{"1":"11","2":"5"}},{"t":"case","label":"Limtiaco v. Camacho","cite":"549 U.S. 483","y":2007,"id":"2006/06-116","sc":1,"sum":"The majority opinion by Justice Clarence Thomas held that, contrary to the Guam Supreme Court's interpretation, the phrase must mean the assessed value for tax purposes of property on Guam. \"The word 'tax' modifies 'valuation,' not 'property,'\" the Court reasoned, so \"tax valuation\" \"refers to the type of valuation to be conducted, not the object that is valued.\" The dissenting Justices argued that deciding the case on the basis of textual analysis and comparison to state debt limitations would amount to a \"coin toss.\" In the dissenters' view, Congress's purpose was to set a \"hard cap\" on debt, which would indicate that the debt limitation should be based on the full market (appraised) value of property on Guam rather than dependent on the changeable assessment rate.","sumSrc":"Oyez","by":{"1":"16","2":"7"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"1":"21, 26"}},{"t":"case","label":"Marie v. Allied Home Mortg. Corp.","cite":"402 F.3d 1","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/402/1/","by":{"1":"11","2":"5"}},{"t":"case","label":"Martinez v. Sullivan","cite":"874 F.2d 751","y":1989,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/874/751/","by":{"1":"11","2":"5"}},{"t":"case","label":"Missouri v. Jenkins","cite":"495 U.S. 33","y":1990,"id":"1989/88-1150","sc":1,"sum":"The Court held that the District Court \"abused its discretion\" by imposing a specific tax increase.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Mobley v. C.I.A.","cite":"806 F.3d 568","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/806/568/","sum":"Finding that equitable considerations excused the untimely filing of a motion under Civil Rule 59(e).","sumSrc":"brief:1","by":{"1":"29, 34"}},{"t":"case","label":"Morse v. United States","cite":"270 U.S. 151","y":1926,"id":"scdb/1925-069","sc":1,"by":{"1":"15"}},{"t":"case","label":"Robertson v. Monsanto Co.","cite":"287 F. App’x 354","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/287/354/","by":{"1":"11","2":"6"}},{"t":"case","label":"Rodriguez v. Banco Cent.","cite":"790 F.2d 172","y":1986,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/790/172/","sum":"Finding that Rule 59(e) applies to interlocutory orders based on Rule 54(a) and noting that “[l]ittle purpose would be served in penalizing a party for requesting a district court to reconsider a disputed interlocutory ruling before attempting to take its grievance to the court of appeals”.","sumSrc":"brief:1","by":{"1":"11, 12"}},{"t":"case","label":"Schacht v. United States","cite":"398 U.S. 58","y":1970,"id":"1969/628","sc":1,"sum":"Petitioner, who participated in a skit performed several times in front of an Armed Forces induction center demonstrating opposition to American involvement in the Vietnam conflict, was convicted by a jury of violating 18 U. S. C. § 702, which makes criminal the unauthorized wearing of an American military uniform or part thereof. Petitioner alleged that he was authorized to wear the uniform by 10 U. S. C. § 772 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 42","2":"16"}},{"t":"case","label":"Smith v. Barry","cite":"502 U.S. 244","y":1992,"id":"1991/90-7477","sc":1,"sum":"A document intended to serve as an appellate brief may qualify as the notice of appeal required by Rule 3. So long as such a document is filed within the time allowed by Rule 4 for a notice of appeal and satisfies Rule 3(c)'s requirements as to the content of such a notice, it may be treated as the \"functional equivalent\" of the formal notice demanded by Rule 3. Torres v. Oakland Scavenger Co., 487 U. S. 312, 317. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Sci.-Atlanta, Inc.","cite":"551 U.S. 1180","y":2007,"url":"https://supreme.justia.com/cases/federal/us/551/1180/","sc":1,"sum":"Recognizing that nonjurisdictional time limitations “may be waived or mitigated in exercising reasonable equitable discretion[]”.","sumSrc":"brief:1","by":{"1":"41"}},{"t":"case","label":"Surowitz v. Hilton Hotels Corp.","cite":"383 U.S. 363","y":1966,"id":"1965/161","sc":1,"sum":"PgahttAwaecplaenhhRatRaaccniafthxnopasrnaetcfaooiduuahipmdtasiptdttmroidlliicilteDopeenoonapatapltpnnbpoivnnnvsalhicslrleaoers2eesniaoea1aaaltito3tstrtg1cmiisnlrtibotit,fenalte,uiiomtnyy(ifoecfatdaobtiaon\"fotnnheegio)fnnrnobwp'dnesensrCmeosoefterste,tahrtofcooihheshs'ettogscftboasppdueahhtehonfkhyhmdloereefsertifohtevaairinnhmFcpcghwofliggdoafotledofsenialifaherpelimuodmrldfiealdlodiisonstaegrednecnasmhu'p,eutgrarhr …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Swierkiewicz v. Sorema N.A.","cite":"534 U.S. 506","y":2002,"id":"2001/00-1853","sc":1,"sum":"The Court held that an employment discrimination complaint need not include specific facts establishing a prima facie case under the framework of McDonnell Douglas Corp. v. Green and instead must contain only \"a short and plain statement of the claim showing that the pleader is entitled to relief,\" pursuant to Rule 8(a)(2) of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"U.S. Bancorp Mortg. Co. v. Bonner Mall P’ship","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"United States v. Eleven Vehicles, Their Equip. & Accessories","cite":"200 F.3d 203","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/200/203/","sum":"Noting that “both the Supreme Court and [the Third Circuit] have recognized an equitable exception to Rule 59”.","sumSrc":"brief:1","by":{"1":"34"}},{"t":"case","label":"United States v. Wong","cite":"135 S. Ct. 1625","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1625/","sc":1,"sum":"Recognizing, in interpreting a federal statute of limitations, that a filing deadline is a “quintessential claim-processing rule” that is subject to equitable tolling.","sumSrc":"brief:1","by":{"1":"21, 34"}},{"t":"case","label":"White v. New Hampshire Dep’t of Emp’t Sec.","cite":"455 U.S. 445","y":1982,"id":"1981/80-5887","sc":1,"sum":"Rule 59(e) is not applicable to postjudgment requests for attorney's fees under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10","2":"5"}},{"t":"case","label":"Wolfsohn v. Hankin","cite":"376 U.S. 203","y":1964,"id":"1963/680","sc":1,"sum":"Recognizing “the ordinary rule” that an appeal need not be filed while a petition for rehearing is under consideration.","sumSrc":"brief:1","by":{"1":"28, 44"}},{"t":"case","label":"Yee v. Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"53"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"op":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Zipes v. Trans World Airlines","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)","(e)","(a)(1)"],"stext":{"head":"§1292. Interlocutory decisions","paras":[[0,"(a) Except as provided in subsections (c) and (d) of this section, the courts of appeals shall have jurisdiction of appeals from:"],[1,"(1) Interlocutory orders of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, or of the judges thereof, granting, continuing, modifying, refusing or dissolving injunctions, or refusing to dissolve or modify injunctions, except where a direct review may be had in the Supreme Court;"],[1,"(2) Interlocutory orders appointing receivers, or refusing orders to wind up receiverships or to take steps to accomplish the purposes thereof, such as directing sales or other disposals of property;"],[1,"(3) Interlocutory decrees of such district courts or the judges thereof determining the rights and liabilities of the parties to admiralty cases in which appeals from final decrees are allowed."],[0,"(b) When a district judge, in making in a civil action an order not otherwise appealable under this section, shall be of the opinion that such order involves a controlling question of law as to which there is substantial ground for difference of opinion and that an immediate appeal from the order may materially advance the ultimate termination of the litigation, he shall so state in writing in such order. The Court of Appeals which would have jurisdiction of an appeal of such action may thereupon, in its discretion, permit an appeal to be taken from such order, if application is made to it within ten days after the entry of the order: Provided, however, That application for an appeal hereunder shall not stay proceedings in the district court unless the district judge or the Court of Appeals or a judge thereof shall so order."],[0,"(c) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction—"],[1,"(1) of an appeal from an interlocutory order or decree described in subsection (a) or (b) of this section in any case over which the court would have jurisdiction of an appeal under section 1295 of this title; and"],[1,"(2) of an appeal from a judgment in a civil action for patent infringement which would otherwise be appealable to the United States Court of Appeals for the Federal Circuit and is final except for an accounting."],[0,"(d)(1) When the chief judge of the Court of International Trade issues an order under the provisions of section 256(b) of this title, or when any judge of the Court of International Trade, in issuing any other interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(2) When the chief judge of the United States Court of Federal Claims issues an order under section 798(b) of this title, or when any judge of the United States Court of Federal Claims, in issuing an interlocutory order, includes in the order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals for the Federal Circuit may, in its discretion, permit an appeal to be taken from such order, if application is made to that Court within ten days after the entry of such order."],[0,"(3) Neither the application for nor the granting of an appeal under this subsection shall stay proceedings in the Court of International Trade or in the Court of Federal Claims, as the case may be, unless a stay is ordered by a judge of the Court of International Trade or of the Court of Federal Claims or by the United States Court of Appeals for the Federal Circuit or a judge of that court."],[0,"(4)(A) The United States Court of Appeals for the Federal Circuit shall have exclusive jurisdiction of an appeal from an interlocutory order of a district court of the United States, the District Court of Guam, the District Court of the Virgin Islands, or the District Court for the Northern Mariana Islands, granting or denying, in whole or in part, a motion to transfer an action to the United States Court of Federal Claims under section 1631 of this title."],[0,"(B) When a motion to transfer an action to the Court of Federal Claims is filed in a district court, no further proceedings shall be taken in the district court until 60 days after the court has ruled upon the motion. If an appeal is taken from the district court's grant or denial of the motion, proceedings shall be further stayed until the appeal has been decided by the Court of Appeals for the Federal Circuit. The stay of proceedings in the district court shall not bar the granting of preliminary or injunctive relief, where appropriate and where expedition is reasonably necessary. However, during the period in which proceedings are stayed as provided in this subparagraph, no transfer to the Court of Federal Claims pursuant to the motion shall be carried out."],[0,"(e) The Supreme Court may prescribe rules, in accordance with section 2072 of this title, to provide for an appeal of an interlocutory decision to the courts of appeals that is not otherwise provided for under subsection (a), (b), (c), or (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1292?type=usc&year=mostrecent&link-type=html"},"head":"§1292. Interlocutory decisions","tname":"Judiciary and Judicial Procedure","by":{"1":"38, 52, 38","2":"5, 6"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","subs":["(c)"],"by":{"1":"45"}},{"t":"rule","label":"Fed. R. App. P. 3","url":"https://www.law.cornell.edu/rules/frap/rule_3","subs":["(a)","(a)(1)","(a)(2)","(a)(4)"],"by":{"1":"36, 45, 36, 37, 36, 37, 37, 38","2":"18, 19, 18"}},{"t":"rule","label":"Fed. R. App. P. 4","url":"https://www.law.cornell.edu/rules/frap/rule_4","subs":["(a)","(a)(1)(A)","(a)(4)","(a)(4)(A)","(a)(4)(A)(iv)","(a)(5)(C)","(a)(1)","(b)"],"by":{"1":"17, 17, 36, 18, 17, 29, 11, 15, 17, 40","2":"9, 9, 10, 9, 9, 7"}},{"t":"rule","label":"Fed. R. App. P. 6","url":"https://www.law.cornell.edu/rules/frap/rule_6","subs":["(b)(1)(A)","(b)(2)(A)(i)","(b)"],"by":{"1":"38, 18, 18","2":"15"}},{"t":"rule","label":"Fed. R. App. P. 15","url":"https://www.law.cornell.edu/rules/frap/rule_15","subs":["(d)"],"by":{"1":"33"}},{"t":"rule","label":"Fed. R. Civ. P. 1","url":"https://www.law.cornell.edu/rules/frcp/rule_1","by":{"1":"5, 26, 32"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"1":"25"}},{"t":"rule","label":"Fed. R. Civ. P. 7","url":"https://www.law.cornell.edu/rules/frcp/rule_7","subs":["(b)(1)","(b)(1)(A)"],"by":{"1":"1, 4, 12"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(h)(1)","(h)(3)"],"by":{"1":"42, 42"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(a)"],"by":{"1":"2, 9, 11, 12","2":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 55","url":"https://www.law.cornell.edu/rules/frcp/rule_55","subs":["(b)(1)"],"by":{"1":"42"}},{"t":"rule","label":"Fed. R. Civ. P. 58","url":"https://www.law.cornell.edu/rules/frcp/rule_58","subs":["(c)(2)(B)"],"by":{"1":"34"}},{"t":"rule","label":"Fed. R. Civ. P. 59","url":"https://www.law.cornell.edu/rules/frcp/rule_59","subs":["(e)","(a)(1)","(a)(2)","(b)","(c)"],"by":{"1":"34, passim","2":"4, 4, 4, 4, 4, 5, 6"}},{"t":"rule","label":"Fed. R. Civ. P. 82","url":"https://www.law.cornell.edu/rules/frcp/rule_82","by":{"1":"29"}},{"t":"case","label":"Boaz v. Mutual Life Ins. Co. of New York","cite":"146 F.2d 321","y":1944,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/146/321/","by":{"2":"5"}},{"t":"case","label":"Cobell v. Jewell","cite":"802 F.3d 12","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/802/12/","by":{"2":"4"}},{"t":"case","label":"Houston v. Lack","cite":"487 U.S. 266","y":1988,"id":"1987/87-5428","sc":1,"sum":"Under Rule 4(a)(1), pro se prisoners' notices of appeal are \"filed\" at the moment of delivery to prison authorities for forwarding to the district court, Cf. Fallen v. United States, 378 U. S. 139 (Stewart, J., concurring). Unskilled in law, unaided by counsel, and unable to leave the prison, a pro se prisoner's control over the processing of his notice necessarily ceases as soon as he hands it over to the only …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"23"}},{"t":"case","label":"McClendon v. United States","cite":"892 F.3d 775","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/775/","by":{"2":"4"}},{"t":"case","label":"Procunier v. Navarette","cite":"434 U.S. 555","y":1978,"id":"1977/76-446","sc":1,"sum":"The Court of Appeals erred in reversing the District Court's summary judgment for petitioners.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"2":"2, 12"}},{"t":"case","label":"Stone v. I.N.S.","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"135 S. Ct. 1625","y":2015,"id":"2014/13-1074","sc":1,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"United States v. Mendenhall","cite":"446 U.S. 544","y":1980,"id":"1979/78-1821","sc":1,"sum":"The judgment is reversed, and the case is remanded. Pp. 550-560; 560-566. 596 F. 2d 706, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}}]};